    {
      "ref": "[D185]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice.",
      "stance": "neutral",
      "quote": "Minecraft is rated PEGI 7 and ESRB Everyone 10+."
    },
    {
      "ref": "[D185]",
      "area": "content",
      "claim": "A parent reports that the game includes mild fantasy violence.",
      "stance": "risk",
      "quote": "The game’s blocky visuals and non-graphic style make the violence less intense than many action games, but the combat is still present."
    },
    {
      "ref": "[D185]",
      "area": "contact",
      "claim": "A parent reports that multiplayer can expose kids to strangers and inappropriate chat.",
      "stance": "risk",
      "quote": "Multiplayer can be great with friends and family, but it also introduces online safety considerations."
    },
    {
      "ref": "[D185]",
      "area": "money",
      "claim": "A parent reports that the game may include in-app purchases.",
      "stance": "risk",
      "quote": "Marketplace purchases may be available (especially on Bedrock)."
    },
    {
      "ref": "[D185]",
      "area": "data",
      "claim": "A parent reports that the game collects data for account management and may share with third parties.",
      "stance": "risk",
      "quote": "Most versions require a Microsoft account. Child accounts are connected to a parent’s account. This allows parents to manage settings like multiplayer access, chat permissions, and purchase approvals."
    },
    {
      "ref": "[D185]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has regulatory actions in South Korea.",
      "stance": "risk",
      "quote": "Child accounts (typically for players under 16, or under 19 in South Korea) are connected to a parent’s account."
    }
  ]
}
